DO $s$ DECLARE n int; c text; p text; m text; v bool; BEGIN
  SELECT count(*) INTO n FROM pg_class i JOIN pg_namespace ns ON ns.oid=i.relnamespace
   WHERE ns.nspname='public' AND i.relname='idx_evidence_versions_evidence_id_approved' AND i.relkind='i';
  IF n <> 1 THEN RAISE EXCEPTION 'I-3 idx_evidence_versions_evidence_id_approved index count measured=% expected=1', n; END IF;
  SELECT t.relname, pg_get_expr(x.indpred, x.indrelid), am.amname, x.indisvalid
    INTO m, p, c, v FROM pg_index x
    JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_class t ON t.oid=x.indrelid
    JOIN pg_am am ON am.oid=i.relam WHERE i.relname='idx_evidence_versions_evidence_id_approved';
  IF m <> 'evidence_versions' THEN RAISE EXCEPTION 'I-3 relation measured=% expected=evidence_versions', m; END IF;
  IF c <> 'btree' THEN RAISE EXCEPTION 'I-3 access method measured=% expected=btree', c; END IF;
  IF v IS NOT TRUE THEN RAISE EXCEPTION 'I-3 indisvalid measured=% expected=true', v; END IF;
  SELECT string_agg(a.attname, ',' ORDER BY k.ord) INTO c FROM pg_index x
    JOIN pg_class i ON i.oid=x.indexrelid
    JOIN LATERAL unnest(x.indkey) WITH ORDINALITY AS k(attnum, ord) ON true
    JOIN pg_attribute a ON a.attrelid=x.indrelid AND a.attnum=k.attnum
   WHERE i.relname='idx_evidence_versions_evidence_id_approved' GROUP BY x.indexrelid;
  IF c <> 'evidence_id' THEN RAISE EXCEPTION 'I-3 key columns/ORDER measured=% expected=evidence_id', c; END IF;
  IF p IS NULL THEN RAISE EXCEPTION 'I-3 idx_evidence_versions_evidence_id_approved must be PARTIAL but pg_index.indpred is NULL'; END IF;
  IF p NOT LIKE '%review_status%' OR p NOT LIKE '%approved%' THEN RAISE EXCEPTION 'I-3 predicate mismatch: measured=% expected~=review_status = ''approved''', p; END IF;
END $s$;

